import os
import re
import subprocess
import sys
import zipfile
from xml.etree import ElementTree as ET

# Mandatory skill initialization before spreadsheet operations
init_script = os.path.join(
    os.path.dirname(os.path.abspath(__file__)),
    ".codex", "skills", "xlsx", "resources", "file_check.sh",
)
subprocess.run(["bash", init_script], check=True)

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
RID = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"


def col_to_idx(ref):
    idx = 0
    for ch in re.match(r"[A-Z]+", ref).group(0):
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1


def cell_value(cell, shared):
    t = cell.get("t")
    if t == "inlineStr":
        is_el = cell.find("m:is", NS)
        if is_el is None:
            return None
        return "".join(x.text or "" for x in is_el.iter() if x.tag.endswith("}t"))
    v = cell.find("m:v", NS)
    if v is None or v.text is None:
        return None
    if t == "s":
        return shared[int(v.text)]
    if t == "b":
        return v.text == "1"
    return v.text


def parse_workbook(zf):
    wb = ET.fromstring(zf.read("xl/workbook.xml"))
    rels = ET.fromstring(zf.read("xl/_rels/workbook.xml.rels"))
    rel_map = {rel.get("Id"): rel.get("Target") for rel in rels}
    sheets = []
    for sh in wb.find("m:sheets", NS):
        target = rel_map[sh.get(RID)]
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        sheets.append((sh.get("name"), target))
    return sheets


def load_sheet(zf, target, shared):
    root = ET.fromstring(zf.read(target))
    data = root.find("m:sheetData", NS)
    rows = []
    for row in data.findall("m:row", NS):
        record = {}
        for cell in row.findall("m:c", NS):
            ref = cell.get("r")
            if not ref:
                continue
            record[col_to_idx(ref)] = cell_value(cell, shared)
        rows.append(record)
    return rows


def to_number(val):
    if val is None:
        return None
    if isinstance(val, bool):
        return None
    if isinstance(val, (int, float)):
        return val
    try:
        return float(val)
    except (TypeError, ValueError):
        return None


path = "budget.xlsx"
if not os.path.exists(path):
    sys.exit(f"File not found: {path}")

with zipfile.ZipFile(path) as zf:
    if "xl/sharedStrings.xml" in zf.namelist():
        shared_root = ET.fromstring(zf.read("xl/sharedStrings.xml"))
        shared = []
        for si in shared_root.findall("m:si", NS):
            shared.append("".join(x.text or "" for x in si.iter() if x.tag.endswith("}t")))
    else:
        shared = []

    sheets = parse_workbook(zf)
    print("Sheets:", [name for name, _ in sheets])

    for name, target in sheets:
        print(f"\n=== Sheet: {name} ===")
        rows = load_sheet(zf, target, shared)
        if not rows:
            print("(empty)")
            continue

        max_col = max(max(r.keys()) for r in rows)
        header = [rows[0].get(c) for c in range(max_col + 1)]
        print("Columns:", header)

        table = []
        for r in rows[1:]:
            table.append([r.get(c) for c in range(max_col + 1)])

        numeric = [c for c in range(max_col + 1)
                   if any(to_number(row[c]) is not None for row in table)]
        cat_cols = [c for c in range(max_col + 1)
                    if c not in numeric and any(row[c] is not None for row in table)]

        if cat_cols and len(numeric) == 1:
            c = numeric[0]
            cat = cat_cols[0]
            totals = {}
            for row in table:
                key = row[cat] if row[cat] is not None else "(blank)"
                val = to_number(row[c])
                if val is None:
                    val = 0.0
                totals[key] = totals.get(key, 0.0) + val
            print(f"\nTotals by {header[cat]!r} ({header[c]!r}):")
            for k in sorted(totals, key=str):
                print(f"  {k}: {totals[k]:,.2f}")
            print(f"\nGRAND TOTAL ({header[c]}): {sum(totals.values()):,.2f}")
        else:
            for c in numeric:
                total = sum(to_number(row[c]) or 0.0 for row in table)
                print(f"TOTAL ({header[c]}): {total:,.2f}")

